/* Keep kit chrome legible under Windows High Contrast using system colors. */
@media (forced-colors: active) {
  :where(
    [data-df="button"],
    [data-df="switch"],
    [data-df="tabs-trigger"],
    [data-df="toggle-group-item"],
    [data-df="content-switcher-item"],
    [data-df="choice-chip"],
    [data-df="select-trigger"],
    [data-df="option-list-trigger"],
    [data-df="popover-trigger"],
    [data-df="input"]
  ):focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 1px;
  }

  :where(
    [data-df="popover-content"],
    [data-df="tooltip-content"],
    [data-df="option-list-content"],
    [data-df="select-trigger"],
    [data-df="input"],
    [data-df="input-field"],
    [data-df="badge"]
  ) {
    border: 1px solid CanvasText;
  }

  :where(
    [data-df="list-item"][data-state="selected"]:not([data-disabled]),
    [data-df="list-item"][data-highlighted]:not([data-disabled]):not([data-readonly]),
    [data-df="list-item"][data-active]:not([data-disabled]):not([data-readonly])
  ) {
    forced-color-adjust: none;
    background-color: Highlight;
    color: HighlightText;
  }

  :where(
    [data-df="tabs-trigger"][aria-selected="true"],
    [data-df="toggle-group-item"][data-state="on"],
    [data-df="content-switcher-item"][data-state="on"]
  ) {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }

  :where([data-df="switch"][data-state="checked"]) {
    forced-color-adjust: none;
    background-color: Highlight;
  }

  :where([data-df="switch"][data-state="checked"] [data-df="switch-thumb"]) {
    background-color: HighlightText;
  }

  :where([data-df="nav-rail-item"][data-state="active"]) {
    forced-color-adjust: none;
    color: HighlightText;
  }

  :where(
    [data-df="nav-rail-item"][data-state="active"] [data-df="nav-rail-item-icon"]
  ) {
    background-color: Highlight;
    color: HighlightText;
  }
}

